def run(context):
    # Obtain holdings and latest stage data
    holdings = context['portfolio_state']
    latest_stage_data = context['sector_exposure']

    # Simple rules for add or trim candidates
    add_candidates = []
    trim_candidates = []

    for holding in holdings:
        matching_data = next((item for item in latest_stage_data if item['symbol'] == holding['symbol']), None)
        if matching_data:
            if matching_data['trading_signal'] in ['BUY', 'STRONG_BUY'] and matching_data['stage'] == 'STAGE_2':
                add_candidates.append(holding['symbol'])
            elif matching_data['trading_signal'] == 'SELL':
                trim_candidates.append(holding['symbol'])

    return {
        'add_candidates': add_candidates,
        'trim_candidates': trim_candidates,
        'risk_flags': []
    }

